-- =============================================================================
-- Seed PM quiz questions — Modules 1–9 (15 questions each = 135 total)
-- AI Project Manager & Delivery Leader (pm-v1)
-- Apply AFTER structure and content migrations.
-- Uses direct INSERT (idempotent check by module).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.fill_pm_exam_a(p_mod int, p_payload jsonb)
RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  cid uuid; ch uuid; qz uuid; rec jsonb; i int := 0;
BEGIN
  SELECT id INTO cid FROM public.courses
    WHERE title = 'AI Project Manager & Delivery Leader'
      AND curriculum_version = 'pm-v1';
  SELECT id INTO ch FROM public.chapters
    WHERE course_id = cid AND order_index = p_mod;
  SELECT id INTO qz FROM public.quizzes
    WHERE chapter_id = ch AND quiz_type = 'chapter_end';
  IF qz IS NULL THEN RAISE NOTICE 'no exam for module %', p_mod; RETURN; END IF;
  IF EXISTS (SELECT 1 FROM public.quiz_questions WHERE quiz_id = qz) THEN
    RAISE NOTICE 'module % already has questions — skipping', p_mod; RETURN;
  END IF;
  FOR rec IN SELECT * FROM jsonb_array_elements(p_payload) LOOP
    i := i + 1;
    INSERT INTO public.quiz_questions
      (quiz_id, question_text, options, correct_answer_index, explanation,
       order_index, competency, translations)
    VALUES (qz, rec->>'q', rec->'opts', (rec->>'a')::int, rec->>'exp',
       i, rec->>'competency', '{}'::jsonb);
  END LOOP;
  RAISE NOTICE 'module %: inserted % questions', p_mod, i;
END;
$fn$;

-- ── MODULE 1: PM Fundamentals & AI Era ───────────────────────────────────────
SELECT pg_temp.fill_pm_exam_a(1, '[
{"q":"You are starting a new project and must choose a delivery framework. The requirements are well-defined, the technology is proven, and regulatory sign-off must occur before any development begins. Which framework is most appropriate?","opts":["Agile Scrum, because it allows for continuous feedback","Waterfall, because sequential phases support the fixed requirements and mandatory gate approval","Kanban, because it optimizes flow without planning overhead","SAFe, because large frameworks handle regulatory complexity best"],"a":1,"exp":"Waterfall is appropriate when requirements are stable, technology is mature, and regulatory gates require complete phase sign-off before proceeding. Agile and Kanban are suited to evolving requirements. SAFe is designed for large multi-team programs, not single projects with fixed scope.","competency":"pm:fundamentals"},
{"q":"PMBOK 7th edition replaced the 10 knowledge areas with 12 project management principles. Which of the following is one of those principles?","opts":["Manage cost first, schedule second","Be a diligent, respectful, and caring steward","Always use a predictive lifecycle","Eliminate stakeholder involvement until delivery"],"a":1,"exp":"PMBOK 7th edition''s 12 principles include ''Be a diligent, respectful, and caring steward'' — reflecting a shift from process-centric to value-centric thinking. PMBOK 7 no longer prescribes lifecycle type or prioritizes any one constraint above others.","competency":"pm:fundamentals"},
{"q":"An AI PM tool flags that your project has a schedule risk based on historical velocity data from similar projects. What is the correct response?","opts":["Dismiss the alert — AI tools cannot understand project context","Immediately escalate to the sponsor and revise the project plan","Treat the AI output as an input to your risk assessment, validate with your team, and investigate the flagged tasks before deciding on action","Accept the AI recommendation without review since it is data-driven"],"a":2,"exp":"AI PM tools generate hypotheses, not decisions. The PM validates AI outputs against project context, team knowledge, and current task status before acting. Dismissing AI alerts wastes a valuable signal; accepting them uncritically creates false urgency.","competency":"pm:fundamentals"},
{"q":"Which project lifecycle phase produces the project charter?","opts":["Planning","Execution","Initiating","Closing"],"a":2,"exp":"The project charter is produced in the Initiating phase. It authorizes the project, defines high-level scope, names the project manager, and documents initial constraints and assumptions. Without a signed charter, the PM has no formal authority to allocate resources.","competency":"pm:fundamentals"},
{"q":"A hybrid delivery framework combines predictive and adaptive elements. In which scenario is hybrid MOST appropriate?","opts":["When the entire project is well-defined and stakeholders resist change","When requirements are unknown and the organization is fully Agile","When some deliverables are well-defined (predictive) while others involve innovation or evolving requirements (adaptive)","When the project team is distributed and communication is difficult"],"a":2,"exp":"Hybrid frameworks serve projects with mixed certainty profiles. A construction project might manage the physical build predictively while running adaptive sprints for the digital control systems. Hybrid is not a default — it requires deliberate design of which elements use which approach.","competency":"pm:fundamentals"},
{"q":"The triple constraint in project management refers to:","opts":["Cost, Quality, and Stakeholder Satisfaction","Scope, Schedule, and Cost — changes to one affect the others","Risk, Issue, and Change","People, Process, and Technology"],"a":1,"exp":"The triple constraint (iron triangle) is Scope-Schedule-Cost. These are interdependent: increasing scope without increasing time or budget degrades quality. PMs must communicate trade-offs explicitly; stakeholders often request scope increases without understanding the cost or schedule impact.","competency":"pm:fundamentals"},
{"q":"You are managing a software project and your sponsor asks you to use ''whatever methodology the team prefers.'' What should you do first?","opts":["Default to Agile Scrum since it is most popular","Poll the team and adopt the majority vote","Assess the project characteristics (requirement stability, team maturity, stakeholder availability, regulatory constraints) before selecting an appropriate framework","Select waterfall to ensure predictability"],"a":2,"exp":"Framework selection should be driven by project characteristics, not team preference alone. Assess: How stable are requirements? How available are stakeholders for feedback? Are there regulatory gates? What is the team''s delivery maturity? The right framework emerges from these answers.","competency":"pm:fundamentals"},
{"q":"Which PMBOK 7th edition performance domain focuses on how the project team interacts and collaborates?","opts":["Stakeholder Performance Domain","Team Performance Domain","Delivery Performance Domain","Planning Performance Domain"],"a":1,"exp":"The Team Performance Domain covers team culture, collaboration, leadership styles, and how the PM develops a high-performing team. PMBOK 7 elevated people and team dynamics from a knowledge area to a core performance domain, reflecting modern PM practice.","competency":"pm:fundamentals"},
{"q":"An AI-powered project management platform automatically updates your project schedule based on task completion data. What risk does this introduce?","opts":["The schedule will always be accurate","Team members may stop manually tracking progress","The AI may propagate incorrect assumptions or stale data without PM review, creating a false sense of schedule health","AI scheduling is more reliable than human judgment, so there is no risk"],"a":2,"exp":"Automated schedule updates are only as good as the underlying data. If task completion data is inaccurate or lag information is missing, the AI will produce a schedule that looks healthy but is not. PMs must periodically audit AI-generated schedule updates against ground truth.","competency":"pm:fundamentals"},
{"q":"What distinguishes a program from a project?","opts":["Programs are smaller than projects","A program is a collection of related projects managed in a coordinated way to obtain benefits and control not available from managing them individually","Programs are always Agile; projects are always waterfall","Programs do not have budgets"],"a":1,"exp":"A program manages related projects together to realize strategic benefits that individual projects cannot achieve alone. For example, a digital transformation program might contain projects for CRM implementation, process redesign, and change management — all interdependent.","competency":"pm:fundamentals"},
{"q":"You are a PM in an organization shifting from waterfall to Agile. A senior developer insists the team should continue writing detailed functional specifications before any coding begins. How do you respond?","opts":["Agree — detailed specifications always improve quality","Immediately eliminate all documentation","Acknowledge the value of clarity while explaining that Agile documentation is just enough, just in time — and work with the developer to identify which specifications add genuine value in the new context","Escalate to HR as a compliance issue"],"a":2,"exp":"Resistance to Agile often reflects genuine concerns about quality and clarity. The PM acknowledges valid needs while distinguishing between documentation that enables delivery and documentation that delays it. ''Working software over comprehensive documentation'' does not mean no documentation.","competency":"pm:fundamentals"},
{"q":"What is the primary purpose of a project management information system (PMIS)?","opts":["To automate all project decisions","To replace the project manager","To provide a centralized platform for planning, tracking, communicating, and reporting project information — supporting PM decision-making","To generate automated status reports for stakeholders"],"a":2,"exp":"A PMIS (e.g., MS Project, Jira, Smartsheet) centralizes project data, enabling the PM to analyze schedule, cost, resource, and risk information in one place. It supports decisions — it does not make them. AI-enhanced PMIS tools add predictive analytics to this foundation.","competency":"pm:fundamentals"},
{"q":"Which statement best describes the role of the project sponsor?","opts":["The sponsor manages day-to-day project activities","The sponsor approves timesheets","The sponsor provides executive authority, secures funding, removes organizational barriers, and is accountable for realizing project benefits","The sponsor is responsible for writing the project charter"],"a":2,"exp":"The sponsor owns the business case and is accountable for benefit realization. The PM is accountable for delivery. Without an active sponsor, projects lose executive air cover when cross-organizational conflicts arise. The PM should actively manage the sponsor relationship, not just report to them.","competency":"pm:fundamentals"},
{"q":"What does ''organizational process assets'' mean in PMBOK terminology?","opts":["Physical assets like computers and servers","The organization''s accumulated plans, processes, policies, procedures, and historical project knowledge that the PM can leverage","Employee performance review records","Budget allocation processes only"],"a":1,"exp":"Organizational process assets (OPAs) include: templates, historical data, lessons learned repositories, standard policies, and approved supplier lists. Experienced PMs leverage OPAs instead of starting from zero, and they add to them at project closure.","competency":"pm:fundamentals"},
{"q":"A project team member mentions that a competing project is using an AI tool that reduced meeting prep time by 60%. You are under schedule pressure. What is the appropriate PM response?","opts":["Immediately mandate the same tool for your team","Ignore it — unproven tools create risk","Investigate the tool with the team, assess fit for your project context, run a small pilot if promising, and make an evidence-based adoption decision","Wait for your organization to formally approve it first"],"a":2,"exp":"Evidence of effectiveness warrants investigation, not immediate adoption or dismissal. Run a bounded pilot, measure the actual impact on your project, and make a data-driven decision. Waiting for formal organizational approval can cost months of productivity gains in fast-moving AI tooling.","competency":"pm:fundamentals"}
]'::jsonb);

-- ── MODULE 2: Initiation & Business Case ─────────────────────────────────────
SELECT pg_temp.fill_pm_exam_a(2, '[
{"q":"You are asked to write a business case for a new customer portal. Which element is most likely to secure executive approval?","opts":["A detailed technical architecture diagram","A quantified cost-benefit analysis with NPV, payback period, and sensitivity analysis","A list of project risks without mitigation plans","A description of the project methodology to be used"],"a":1,"exp":"Executives approve investments based on financial returns and strategic alignment. A quantified cost-benefit analysis with NPV (Net Present Value), payback period, and sensitivity analysis (''what if costs overrun by 20%?'') speaks the language of capital allocation decisions. Technical diagrams belong in the appendix.","competency":"pm:initiation"},
{"q":"What are the minimum required elements of a project charter?","opts":["Only the project name and sponsor signature","Project purpose, high-level scope, deliverables, milestones, budget, assumptions, constraints, risks, stakeholder list, and PM authority — sufficient to authorize project initiation","A complete WBS and schedule","A detailed risk register with probability and impact scores"],"a":1,"exp":"The charter is the PM''s authorization document. It must contain enough information to authorize spending and resource allocation without over-specifying scope. A charter that includes a detailed WBS is too detailed — that level belongs in the planning phase.","competency":"pm:initiation"},
{"q":"During stakeholder identification, you discover a senior VP who was not included in the initial stakeholder list. She has high power and high interest in the project outcome. What should you do?","opts":["Proceed as planned — adding stakeholders mid-initiation creates scope creep","Add her to the stakeholder register, brief her on project status, understand her requirements, and update the communication plan accordingly","Send her a summary email and consider the obligation fulfilled","Wait until the planning phase to engage her"],"a":1,"exp":"High-power, high-interest stakeholders who are not engaged become blockers. The earlier a missed stakeholder is identified, the lower the cost of engagement. Brief her now, capture her requirements, and ensure her communication preferences are reflected in the communication plan.","competency":"pm:initiation"},
{"q":"What is the primary purpose of a project kick-off meeting?","opts":["To assign all tasks to team members","To create the project schedule","To align the team on project purpose, roles, constraints, and ways of working — establishing shared commitment and a common operating picture","To review the project charter with the sponsor"],"a":2,"exp":"A kick-off meeting establishes the psychological and operational foundation for the project. Team members who understand why the project exists, what success looks like, and how they will work together are more engaged and aligned. A kick-off is not a task assignment meeting.","competency":"pm:initiation"},
{"q":"An AI tool analyzes historical project data and suggests that your project''s business case ROI assumption of 18 months payback is optimistic based on similar projects that averaged 28 months. What is the correct action?","opts":["Reject the AI analysis — it does not know this project''s specifics","Accept the AI''s 28-month figure and revise the business case immediately","Investigate the AI''s comparable projects, identify the drivers of longer payback (e.g., slower adoption, integration costs), and either adjust the assumption or document why this project will differ","Present both figures to the sponsor and let them choose"],"a":2,"exp":"AI historical analysis provides a calibration signal. The PM must understand why comparable projects took longer: was it adoption speed, scope growth, or integration complexity? If those factors do not apply here, document the rationale. If they do, revise the assumption.","competency":"pm:initiation"},
{"q":"What is the difference between assumptions and constraints in project initiation?","opts":["They are the same thing with different names","Assumptions are things believed to be true that have not been confirmed; constraints are real limitations (budget, timeline, resources) imposed on the project","Constraints are flexible; assumptions are fixed","Only constraints appear in the project charter"],"a":1,"exp":"Assumptions (''We assume the API will be ready by Week 6'') create risk if proven false — the PM should actively verify them. Constraints (''The system must go live before fiscal year end'') are non-negotiable limitations that shape planning. Both must be documented explicitly in the charter.","competency":"pm:initiation"},
{"q":"A project sponsor wants to skip the business case and go straight to execution ''because we all know this project is needed.'' What is the risk of skipping the business case?","opts":["There is no significant risk — the sponsor''s support is sufficient","The project loses formal documentation of success criteria, making it impossible to measure benefit realization or make go/no-go decisions at key milestones","Business cases only matter for large projects","The project charter cannot be written without a business case"],"a":1,"exp":"Without a business case, the project lacks a shared definition of success. When the project is in trouble, there is no agreed baseline for trade-off decisions. Benefit realization cannot be measured. The PM should at minimum document assumptions about value, even in a lightweight format.","competency":"pm:initiation"},
{"q":"You are facilitating a kick-off meeting for a cross-functional project with 20 participants. The meeting is two hours long. What is the most important structural element to include?","opts":["A detailed walkthrough of the entire project plan","Time for participants to raise concerns, ask questions, and commit to their roles — not just a PM presentation","A live demo of the project management tool","Individual introductions lasting 5 minutes each"],"a":1,"exp":"Kick-offs fail when they are one-way information dumps. Two-way dialogue — surfacing concerns early, clarifying role expectations, and obtaining verbal commitment — creates the shared ownership that drives project success. Leave at least 30–40% of time for discussion.","competency":"pm:initiation"},
{"q":"Which stakeholder identification technique uses a structured interview process with subject matter experts to surface stakeholders who may not be immediately obvious?","opts":["SWOT analysis","Power/interest grid","Expert judgment — systematically interviewing experienced PMs, domain experts, and current stakeholders to identify who else might be affected by or influence the project","Benchmarking against similar projects"],"a":2,"exp":"Expert judgment is the primary stakeholder identification technique in PMBOK. Experienced practitioners know which organizational roles (legal, compliance, union representatives) are always relevant but easily overlooked. Supplement with document review (org charts, project archives) and stakeholder-identifies-stakeholder snowballing.","competency":"pm:initiation"},
{"q":"What does NPV (Net Present Value) tell you in a project business case?","opts":["The total undiscounted cash flows from the project","The project''s return on investment percentage","The present value of future benefits minus the present value of costs — a positive NPV means the investment creates value in today''s dollars","The time required to recover the initial investment"],"a":2,"exp":"NPV discounts future cash flows to today''s value. A project with $2M in costs and $3M in benefits over 5 years does not simply generate $1M in value — the timing matters. A positive NPV confirms the investment creates value even after accounting for the time value of money.","competency":"pm:initiation"},
{"q":"A key project stakeholder has high power but low interest in the project. According to stakeholder theory, what is the appropriate engagement strategy?","opts":["Engage them intensively with detailed weekly reports","Ignore them — low interest means they will not interfere","Keep them satisfied with periodic briefings on high-level status, escalations, and decisions that require their authority — do not overwhelm them with operational detail","Move them to a low-priority stakeholder category permanently"],"a":2,"exp":"Power/interest grid strategy: high power, low interest = Keep Satisfied. These stakeholders can block the project if they become dissatisfied but do not need weekly operational detail. Brief them on issues requiring their authority; respect their limited bandwidth by keeping communications concise and strategic.","competency":"pm:initiation"},
{"q":"What is the payback period in a business case and what is its limitation?","opts":["It measures the total project profit; the limitation is complexity","It measures how long until cumulative benefits equal cumulative costs; the limitation is that it ignores cash flows beyond the payback point and does not account for the time value of money","It measures ROI percentage; the limitation is it requires NPV calculation","It measures project duration; there is no meaningful limitation"],"a":1,"exp":"Payback period is simple and intuitive but misleading for long-horizon investments. Two projects with 24-month payback may have very different post-payback cash flows. Use payback alongside NPV and IRR for a complete financial picture.","competency":"pm:initiation"},
{"q":"Your sponsor asks you to have the project ''approved and funded'' by end of week. You are still gathering stakeholder requirements for the business case. What should you do?","opts":["Fabricate requirements to meet the deadline","Request the approval for the project initiation phase only, with a planned gate review after requirements gathering is complete","Approve the project based on incomplete information to satisfy the sponsor","Refuse to proceed without a complete business case"],"a":1,"exp":"Phased approval (approve initiation, gate at planning) balances speed with rigor. The PM requests approval to begin and commit to a complete business case by a defined date. This is standard practice in programs with staged funding gates and protects the PM from approving unknown commitments.","competency":"pm:initiation"},
{"q":"Which AI capability is most useful during project initiation?","opts":["Automated code generation for the project deliverables","AI-powered meeting summarization and action item extraction from stakeholder discovery sessions","Automated project closure reports","AI-driven performance management for team members"],"a":1,"exp":"During initiation, PMs conduct many stakeholder interviews and discovery sessions. AI meeting intelligence tools (Otter.ai, Fireflies, Zoom AI) transcribe conversations, extract action items, and identify recurring themes — reducing the manual burden of initiation documentation significantly.","competency":"pm:initiation"},
{"q":"What is the purpose of the stakeholder register created during initiation?","opts":["To track timesheets for project resources","To document each stakeholder''s identity, role, contact information, power/interest level, requirements, communication preferences, and current engagement level — serving as the master stakeholder management document throughout the project","To list all project risks","To record decisions made during the project"],"a":1,"exp":"The stakeholder register is a living document updated throughout the project. At initiation, it captures who stakeholders are and what they need. During execution, it tracks engagement levels and communication effectiveness. PMs who maintain a detailed register are better positioned to manage relationship changes.","competency":"pm:initiation"}
]'::jsonb);

-- ── MODULE 3: Scope Management & WBS ─────────────────────────────────────────
SELECT pg_temp.fill_pm_exam_a(3, '[
{"q":"Your project scope statement has been approved by the sponsor. Two weeks into planning, a key stakeholder requests a new feature that was not included in the original scope. What is the correct process?","opts":["Add the feature immediately to keep the stakeholder happy","Refuse all changes once scope is approved","Document the request as a change request, assess impact on schedule, cost, quality, and risk, present the analysis to the Change Control Board (CCB), and implement only upon CCB approval","Implement the feature in the next phase without formal approval"],"a":2,"exp":"Integrated change control is mandatory for any scope addition. Unauthorized scope additions (gold-plating or scope creep) undermine the project baseline. The CCB review ensures stakeholders understand the trade-offs before approving the change.","competency":"pm:scope"},
{"q":"The 100% rule in WBS creation states that:","opts":["100% of team members must review the WBS","The WBS must contain exactly 100 work packages","The WBS must capture 100% of the project scope — all deliverables, including project management activities — with no more and no less scope than what is defined","100% of work must be assigned to named resources"],"a":2,"exp":"The 100% rule is the most important WBS quality check. If a deliverable is not in the WBS, it is not in the project. If something is in the WBS but not in the scope statement, it should not be there. The WBS is the scope, made visual.","competency":"pm:scope"},
{"q":"What is the lowest level of a WBS called, and what is its significance?","opts":["Task — it is assigned to a specific team member","Milestone — it marks a key date","Work package — the level at which cost, schedule, and resource estimates can be reliably developed and assigned","Activity — the smallest unit of project work"],"a":2,"exp":"Work packages are the WBS deliverables from which activities are then decomposed in schedule development. At work package level, a team can estimate duration, cost, and resources with reasonable accuracy. If a work package cannot be estimated, it needs further decomposition.","competency":"pm:scope"},
{"q":"A requirements traceability matrix (RTM) connects:","opts":["Project tasks to team members","Business requirements to specific deliverables, test cases, and release versions — enabling tracking of requirements through design, build, and test","Risks to mitigation actions","Stakeholders to communication channels"],"a":1,"exp":"The RTM ensures every business requirement has a corresponding deliverable and test case. It is the PM''s tool for scope completeness: if a requirement is not in the RTM, it may not be built or tested. Use it in scope verification to confirm all requirements have been met.","competency":"pm:scope"},
{"q":"What is the difference between scope validation and scope control?","opts":["They are identical processes","Scope validation is gaining formal acceptance of completed deliverables from stakeholders; scope control is monitoring scope and managing changes to the scope baseline","Scope control is a planning activity; validation is a closing activity","Scope validation applies only to the final deliverable"],"a":1,"exp":"Scope validation (Validate Scope process) happens at phase gates and milestones: the stakeholder reviews and formally accepts completed deliverables. Scope control (Control Scope process) is ongoing: monitoring for scope creep, processing change requests, and maintaining the scope baseline integrity.","competency":"pm:scope"},
{"q":"You discover that a development team has been building a feature not in the approved scope because ''the customer will definitely want it.'' This is an example of:","opts":["Good customer service","Proactive scope management","Gold-plating — adding unauthorized scope that increases risk without approved trade-off analysis","An approved change that was not communicated to the PM"],"a":2,"exp":"Gold-plating is adding unrequested scope, even with good intentions. It consumes budget, delays the schedule, and may introduce defects in adjacent functionality. The customer should decide what they want through the change control process, not the development team.","competency":"pm:scope"},
{"q":"A scope statement should include all of the following EXCEPT:","opts":["Product scope description","Project deliverables","Acceptance criteria","Detailed resource assignments and team member names"],"a":3,"exp":"The scope statement defines WHAT will be delivered (product scope, deliverables, acceptance criteria) and explicitly excludes what will NOT be delivered. Resource assignments belong in the resource management plan, not the scope statement.","competency":"pm:scope"},
{"q":"What is an exclusion statement in a project scope statement, and why is it important?","opts":["A legal clause excluding the PM from liability","A list of deliverables that are explicitly out of scope — preventing stakeholders from assuming items are included when they are not","A list of risks that will not be managed","A budget exclusion for unforeseen costs"],"a":1,"exp":"Exclusion statements prevent the most common scope creep trigger: stakeholder assumptions. If stakeholders assume user training is included and it is not explicitly excluded, they will expect it. ''User training is out of scope'' eliminates that ambiguity and makes change requests explicit.","competency":"pm:scope"},
{"q":"An AI tool reviews your project requirements document and flags 12 requirements as ambiguous (containing words like ''fast,'' ''easy,'' and ''flexible''). What should you do?","opts":["Dismiss the flags — these are subjective business terms and are acceptable","Replace all ambiguous requirements with technical specifications written by the development team","Work with stakeholders to add measurable acceptance criteria: ''fast'' becomes ''response time ≤ 2 seconds for 95% of transactions''","Accept the AI''s proposed rewordings automatically"],"a":2,"exp":"Ambiguous requirements cause rework. ''Fast'' means different things to different stakeholders. The PM''s job is to facilitate the conversion of subjective language into measurable acceptance criteria. This is best done with the business stakeholder who wrote the requirement, not the development team or the AI.","competency":"pm:scope"},
{"q":"During a sprint review, stakeholders request five new features. Who has the authority to approve these additions to the project scope?","opts":["The project manager alone","The development team since they will build it","The Change Control Board or designated change authority — not the PM alone or any individual stakeholder","The stakeholder who requested the features"],"a":2,"exp":"Change control authority is defined in the change management plan. On most projects, the PM cannot unilaterally approve scope changes — the CCB (which typically includes the sponsor, PM, and key stakeholders) must assess and approve changes to the approved scope baseline.","competency":"pm:scope"},
{"q":"What is the scope baseline composed of?","opts":["The project schedule and cost estimate","The project charter and stakeholder register","The approved scope statement, WBS, and WBS dictionary — together forming the reference against which scope changes are measured","The requirements document and test plan"],"a":2,"exp":"The scope baseline is the approved, signed-off version of: (1) the scope statement, (2) the WBS, and (3) the WBS dictionary. Changes to any of these require formal change control. The WBS dictionary adds detailed descriptions to each WBS element.","competency":"pm:scope"},
{"q":"You are developing a WBS for a software project. A team member suggests including testing as a single WBS element. What should you recommend?","opts":["Accept it — testing is one activity and should be one element","Expand testing into specific work packages: unit testing, integration testing, user acceptance testing, and performance testing — each with distinct deliverables and estimable effort","Remove testing from the WBS since it is an activity, not a deliverable","Move testing to the schedule instead of the WBS"],"a":1,"exp":"A WBS element called ''testing'' is too large to estimate, assign, or control. Breaking it into specific deliverable-oriented work packages (UAT test scripts, performance test results, test summary report) enables accurate estimation and clear ownership.","competency":"pm:scope"},
{"q":"What triggers a formal change control process?","opts":["Only external stakeholder requests","Only changes that affect the cost baseline","Any proposed change to the scope, schedule, or cost baseline — including internally initiated changes that the PM or team is considering","Only changes that exceed the PM''s financial authority"],"a":2,"exp":"Change control applies to all baseline changes regardless of source or size. A team member''s decision to use a different technical approach that changes schedule or cost is a scope/schedule change requiring CCB review — not a technical decision made in isolation.","competency":"pm:scope"},
{"q":"A client insists they communicated a requirement in a meeting three months ago that was never documented. You cannot find it in any project records. What is the best course of action?","opts":["Accept the claim and add the requirement immediately","Deny the requirement completely","Document the claim, investigate meeting notes and emails, escalate to the sponsor if needed, and process through change control regardless of whether the claim is validated — it represents new or missed scope","Ask the client to provide written proof before acknowledging it"],"a":2,"exp":"Whether the requirement was missed or is new, change control is the correct path. If it was genuinely missed, adding it through change control creates a documented audit trail. If it is new scope, the client understands there will be impact. Either way, RTM documentation prevents future disputes.","competency":"pm:scope"},
{"q":"The WBS dictionary serves what primary purpose?","opts":["It lists dictionary definitions of PM terms","It provides detailed descriptions of each WBS work package, including scope, acceptance criteria, responsible party, and cost/time estimates — enabling consistent understanding across the project team","It is a glossary of technical terms for the development team","It documents stakeholder communication preferences"],"a":1,"exp":"The WBS dictionary is the specification behind each WBS box. Without it, different team members may interpret a work package differently. A WBS dictionary entry for ''System Integration Testing'' specifies: what systems, what test types, what pass/fail criteria, who is responsible, and the estimated effort.","competency":"pm:scope"}
]'::jsonb);

-- ── MODULE 4: Schedule Management ────────────────────────────────────────────
SELECT pg_temp.fill_pm_exam_a(4, '[
{"q":"On a project network diagram, Activity A has an early start of Day 1, early finish of Day 5, late start of Day 4, and late finish of Day 8. What is the total float for Activity A?","opts":["0 days — it is on the critical path","5 days","3 days — calculated as Late Start minus Early Start (4-1)","8 days"],"a":2,"exp":"Total Float = Late Start − Early Start (or Late Finish − Early Finish). 4 − 1 = 3 days. Activity A can be delayed up to 3 days without delaying the project end date. Activities with zero float are on the critical path.","competency":"pm:schedule"},
{"q":"Your project is behind schedule and the sponsor demands recovery without adding resources. Which schedule compression technique is available to you?","opts":["Crashing — adding resources to shorten critical path activities","Fast-tracking — performing activities in parallel that were originally planned sequentially","Resource leveling — redistributing existing resources to optimize utilization","Schedule baseline revision — extending the end date"],"a":1,"exp":"Fast-tracking overlaps sequential activities (e.g., starting design before requirements are fully approved) to compress the schedule without adding budget. It introduces rework risk. Crashing requires additional resources (cost). Resource leveling does not shorten the schedule. Baseline revision is a last resort requiring sponsor approval.","competency":"pm:schedule"},
{"q":"What is the critical path in a project network diagram?","opts":["The longest path from project start to finish with zero float — any delay on this path delays the project end date","The path with the most activities","The path with the highest cost","The path the sponsor considers most important"],"a":0,"exp":"The critical path is the longest duration path through the network. It has zero float — no slack to absorb delays. The PM must monitor critical path activities most closely. There can be multiple critical paths. Near-critical paths (float ≤ 2–3 days) also deserve close monitoring.","competency":"pm:schedule"},
{"q":"A team member estimates Activity B will take 4 days optimistic, 10 days most likely, and 22 days pessimistic. Using three-point PERT estimation, what is the expected duration?","opts":["12 days","11 days — calculated as (O + 4M + P) / 6 = (4 + 40 + 22) / 6 = 11","10 days — the most likely estimate","22 days — always use the pessimistic estimate for risk management"],"a":1,"exp":"PERT three-point estimate: (Optimistic + 4 × Most Likely + Pessimistic) / 6 = (4 + 4×10 + 22) / 6 = (4 + 40 + 22) / 6 = 66 / 6 = 11 days. PERT weights the most likely estimate four times, producing a weighted average more accurate than simple averaging.","competency":"pm:schedule"},
{"q":"What is the difference between free float and total float?","opts":["They are the same calculation with different names","Free float is the delay an activity can absorb without delaying any successor; total float is the delay an activity can absorb without delaying the project end date","Total float is always larger than free float","Free float applies only to the critical path"],"a":1,"exp":"Total float belongs to the path, not the activity. Free float belongs to the individual activity. An activity may have 5 days total float but only 2 days free float if its successor has no buffer. Consuming total float affects all subsequent activities on that path.","competency":"pm:schedule"},
{"q":"Your project schedule shows that crashing Activity X from 10 to 6 days costs $8,000 and crashing Activity Y from 8 to 5 days costs $6,000. Both are on the critical path. Which activity should you crash first to recover 3 days at lowest cost?","opts":["Crash Activity X first because it saves more days","Crash Activity Y first because it has a lower cost per day crashed ($6,000/3 days = $2,000/day vs $8,000/4 days = $2,000/day — evaluate further","Crash both simultaneously","Cannot determine without more information about successor activities"],"a":1,"exp":"Cost slope = Cost / Days Saved. Activity X: $8,000 / 4 days = $2,000/day. Activity Y: $6,000 / 3 days = $2,000/day. Equal cost slopes — either can be crashed first. In practice, evaluate which is less risky to compress and whether crashing reveals a new critical path.","competency":"pm:schedule"},
{"q":"What is resource leveling and what is its trade-off?","opts":["Increasing team size — the trade-off is higher cost","Redistributing resources to eliminate over-allocation — the trade-off is that it typically extends the project schedule","Prioritizing resource allocation to critical path activities only — no trade-off","A technique for reducing project costs — the trade-off is lower quality"],"a":1,"exp":"Resource leveling smooths resource demand by shifting non-critical activities within their float. This resolves over-allocation but extends the schedule if activities must wait for resources to free up. The PM must communicate schedule impact to the sponsor before applying resource leveling.","competency":"pm:schedule"},
{"q":"What is a milestone in project scheduling?","opts":["A major project deliverable that takes multiple weeks to complete","A zero-duration event marking a significant point in the schedule — typically a deliverable approval, phase gate, or key decision point","A task assigned to a senior team member","Any activity with a hard deadline"],"a":1,"exp":"Milestones have zero duration — they mark moments, not work. They are used for: tracking progress at a high level, communicating to stakeholders without exposing schedule detail, and triggering payments in contract-based projects. Milestone slippage is the most visible form of schedule variance.","competency":"pm:schedule"},
{"q":"An AI scheduling tool detects that two critical path activities have the same resource assigned and the combined workload exceeds 100% capacity. What should the PM do?","opts":["Ignore it — resource conflicts are the team''s problem to solve","Automatically approve the AI''s suggested resolution","Review the conflict with the resource manager, evaluate options (extend one activity, fast-track, assign a secondary resource), choose the option with the least schedule and cost impact, and update the schedule baseline through change control if needed","Remove one of the activities from the critical path"],"a":2,"exp":"Resource conflicts on the critical path are schedule risks. The PM must assess options (shifting one activity within its float, obtaining a backup resource, adjusting the sequence) and quantify the schedule impact of each option before acting. AI flags the problem; the PM resolves it.","competency":"pm:schedule"},
{"q":"What is the difference between a Finish-to-Start (FS) dependency and a Start-to-Start (SS) dependency in a network diagram?","opts":["FS means both activities start together; SS means one must finish before the other starts","FS means a successor cannot start until the predecessor finishes; SS means a successor can start when a predecessor starts — enabling parallel progress","They are the same — all activities in a network are sequential","FS applies to critical path activities; SS applies to non-critical activities"],"a":1,"exp":"FS (most common) is sequential: design finishes → build starts. SS enables partial overlap: ''Writing'' starts → ''Editing'' can start once writing begins, even before writing is complete. SS with lag (e.g., SS+3d) means the successor starts 3 days after the predecessor starts.","competency":"pm:schedule"},
{"q":"You are managing a 6-month project. Your current schedule shows a 3-week buffer at the end. A team lead proposes starting two dependent activities simultaneously to ''save time.'' What risk does this create?","opts":["No risk — parallel activities are always faster","Increased rework risk: if the predecessor activity changes, rework in the successor may be required; evaluate the probability and cost of rework against the schedule savings","Loss of the critical path","Reduced team motivation"],"a":1,"exp":"Fast-tracking (overlapping dependent activities) introduces rework risk. If Activity A''s output changes after Activity B has started using it, B must rework. The PM must calculate: expected rework cost × probability of rework vs. schedule savings. If rework risk is low and savings are high, fast-track. Otherwise, reconsider.","competency":"pm:schedule"},
{"q":"What does the schedule baseline represent and when can it be changed?","opts":["The original schedule estimate that should never be changed","The original estimated schedule plus all approved changes — the approved reference point against which actual schedule performance is measured; changed only through formal change control","The current schedule including all team updates","The sponsor''s desired completion date"],"a":1,"exp":"The schedule baseline is the approved plan. It changes only when a formal change request is approved by the CCB. This preserves the audit trail: you can always compare actuals to baseline and explain variance. PMs who update the baseline informally lose the ability to report accurate schedule performance.","competency":"pm:schedule"},
{"q":"A stakeholder asks why the project end date changed when ''only a few small tasks'' slipped. How do you explain critical path impact?","opts":["Small task slippage never affects the project end date","Explain that even small delays on critical path activities directly extend the project end date by the same amount, because there is no float to absorb the delay","Tell the stakeholder the schedule was always inaccurate","Explain that the resource leveling algorithm caused the shift"],"a":1,"exp":"The critical path concept is counterintuitive to many stakeholders. A 3-day slip on a non-critical activity may have zero impact; a 3-day slip on a critical path activity adds 3 days to the end date. Use a simplified network diagram to make this visual when communicating to non-PM audiences.","competency":"pm:schedule"},
{"q":"What is schedule compression crashing, and what is its primary trade-off?","opts":["Removing activities from the scope — the trade-off is reduced deliverables","Adding resources (people, overtime, equipment) to critical path activities to shorten their duration — the trade-off is increased cost","Running all activities in parallel — the trade-off is increased risk","Reducing quality requirements — the trade-off is stakeholder dissatisfaction"],"a":1,"exp":"Crashing accelerates critical path activities by adding resources: additional staff, overtime, specialist contractors, or faster equipment. Cost increases because more resources are consumed in less time. The PM calculates crash cost per day saved and selects the cheapest crashing option that meets the required recovery.","competency":"pm:schedule"},
{"q":"You build a network diagram and identify two paths: Path A (critical) = 30 days, Path B = 27 days. Your sponsor demands a 10-day schedule compression. After crashing Path A by 5 days, what happens to Path B?","opts":["Path B becomes irrelevant since it is not critical","Path B still has 3 days of float — no action needed yet","After crashing Path A by 5 days (now 25 days), Path B (still 27 days) becomes the new critical path — the PM must now crash Path B to achieve further compression","Path B is also automatically shortened by crashing Path A"],"a":2,"exp":"When you crash the critical path, the longest remaining path becomes the new critical path. After crashing A to 25 days: B is now 27 days and becomes critical. To compress further, you must also crash activities on Path B. Crashing one path without monitoring others is a common scheduling error.","competency":"pm:schedule"}
]'::jsonb);

-- ── MODULE 5: Risk Management ─────────────────────────────────────────────────
SELECT pg_temp.fill_pm_exam_a(5, '[
{"q":"You are managing a software migration project. A team member suggests that the legacy system might have undocumented data fields that could break the migration. This is currently unconfirmed. How should it be classified?","opts":["An issue — it is already affecting the project","A risk — it is an uncertain event that may impact the project if it occurs","A constraint — it limits your design options","An assumption — you should assume it will not be a problem"],"a":1,"exp":"A risk is an uncertain future event with potential impact. The undocumented fields are not confirmed (not yet an issue). They belong in the risk register with a probability, impact, and mitigation plan. If they are later confirmed to exist, the risk becomes an issue and the response plan is activated.","competency":"pm:risk"},
{"q":"A risk has a 40% probability of occurring and would cost $50,000 if it did. What is the expected monetary value (EMV) of this risk?","opts":["$50,000","$90,000","$20,000 — calculated as 0.40 × $50,000","$30,000"],"a":2,"exp":"EMV = Probability × Impact = 0.40 × $50,000 = $20,000. EMV is used to calculate the contingency reserve: the sum of EMV across all identified risks provides a statistical estimate of the budget needed to cover identified risks. It does not represent the actual cost if the risk occurs.","competency":"pm:risk"},
{"q":"What is the difference between a risk response strategy of ''mitigate'' and ''transfer''?","opts":["They are the same strategy with different names","Mitigate reduces the probability or impact of a risk; transfer shifts the financial consequence to a third party (insurance, contract clause) without eliminating the risk","Transfer eliminates the risk entirely; mitigate only reduces it","Mitigate applies to threats; transfer applies to opportunities"],"a":1,"exp":"Mitigation: install fire suppression → reduces probability of fire damage. Transfer: purchase property insurance → does not reduce fire probability, but the financial impact falls on the insurer. Both are valid but distinct. Transfer does not eliminate the risk from the register — it changes the owner of the financial impact.","competency":"pm:risk"},
{"q":"A Monte Carlo simulation of your project schedule produces a P80 completion date of March 15 and a P50 date of February 28. The sponsor wants to commit to February 28 publicly. What advice do you give?","opts":["February 28 is fine — use the P50 date for all commitments","Commit to March 15 because it is the safest date","Explain that P50 means a 50% probability of meeting the date — there is an equal chance of finishing late; for a public commitment, the sponsor should consider the P80 date (80% confidence) or communicate the range and most likely date","Use the optimistic estimate from the simulation as the committed date"],"a":2,"exp":"P50 means 50% of simulated project completions finished by that date. For a public commitment where a miss would damage credibility, P80 or P90 is more appropriate. The PM''s role is to help the sponsor understand confidence levels, not just report the most optimistic number.","competency":"pm:risk"},
{"q":"On a probability-impact matrix, a risk with a HIGH probability and LOW impact should be managed by:","opts":["Avoid — eliminate the risk entirely","Transfer — shift it to an insurer","Accept actively — monitor closely and prepare a contingency plan for when it occurs","Escalate immediately to the sponsor"],"a":2,"exp":"High probability, low impact risks are typically accepted actively: monitor them, prepare a lightweight contingency plan, and execute it when they occur. Avoidance (eliminating the risk) may cost more than the impact. Transfer via insurance is disproportionate for low-impact risks.","competency":"pm:risk"},
{"q":"What is a risk trigger, and why is it important in risk response planning?","opts":["The event that causes a risk to occur, used to know when to activate a risk response plan — reducing response time and limiting impact","A formula for calculating EMV","A stakeholder who escalates risks to management","A risk category in the risk breakdown structure"],"a":0,"exp":"A trigger (early warning indicator) tells the PM that a risk is about to materialize. Example: ''If the vendor misses the Week 6 delivery milestone by more than 2 days, activate the backup vendor contingency.'' Triggers enable proactive response rather than reactive crisis management.","competency":"pm:risk"},
{"q":"What is the difference between a contingency reserve and a management reserve?","opts":["They are the same — different names for budget buffer","Contingency reserve covers identified risks (known-unknowns); management reserve covers unidentified risks (unknown-unknowns) and requires sponsor approval to access","Management reserve is larger and always equals 10% of project cost","Contingency reserve is approved by the team; management reserve is approved by the PM"],"a":1,"exp":"Contingency reserve: calculated from identified risk EMV, controlled by the PM, used when a documented risk response is activated. Management reserve: estimated as a percentage of total budget for unforeseeable events, controlled by the sponsor or PMO, requires formal change request to access.","competency":"pm:risk"},
{"q":"You identify a risk that your key technical architect might leave the company during the project. Which risk response strategy is most appropriate?","opts":["Avoid — reassign the architect to a different project","Transfer — include a contractor clause in the architect''s employment contract","Mitigate — cross-train a backup resource and document architecture decisions — reducing the probability of impact if the architect leaves","Accept passively — do nothing and respond if it happens"],"a":2,"exp":"You cannot prevent an employee from leaving (avoidance is not feasible). Transfer is not applicable for personnel risk. Mitigation reduces impact: cross-training a backup, documenting decisions in an architecture decision record, and ensuring knowledge is not bottlenecked in one person.","competency":"pm:risk"},
{"q":"What is Monte Carlo simulation in project risk management?","opts":["A gambling-based estimation technique","A deterministic calculation of the critical path","A statistical technique that runs thousands of simulated project scenarios using probability distributions for activity durations and costs, producing a range of possible outcomes with confidence levels","A risk matrix scoring method used in PMBOK"],"a":2,"exp":"Monte Carlo simulation replaces single-point estimates with probability distributions (e.g., ''this task takes 5–15 days with most likely 8 days''). Running 10,000 simulations produces a probability distribution of project end dates and costs, enabling the PM to communicate confidence levels rather than false point estimates.","competency":"pm:risk"},
{"q":"A risk previously classified as low probability has just increased to high probability because a key supplier announced financial difficulties. What should the PM do?","opts":["Remove it from the risk register since the situation has changed","Leave it classified as low probability to avoid alarming stakeholders","Update the risk register with the new probability assessment, re-evaluate the response plan, escalate to the sponsor if the risk now exceeds acceptable thresholds, and communicate the change in the next status report","Wait for the supplier to formally notify the project before acting"],"a":2,"exp":"Risk registers are living documents. The PM updates risk assessments as conditions change. A risk moving from low to high probability may require an immediate response (activating a backup supplier) rather than waiting. Early escalation prevents surprises for the sponsor.","competency":"pm:risk"},
{"q":"What is a secondary risk?","opts":["The second most important risk on the project","A risk that arises as a direct result of implementing a risk response — must be identified and managed in the same risk register","A risk that affects a secondary stakeholder","A risk with medium probability and medium impact"],"a":1,"exp":"Secondary risks emerge from the response itself. Example: ''We mitigate supply chain risk by using two suppliers'' creates a secondary risk: ''Coordinating two suppliers increases integration complexity.'' Failing to identify secondary risks means your mitigation creates new problems.","competency":"pm:risk"},
{"q":"An AI tool analyzes your project data and identifies a pattern suggesting that database integration tasks on your project type typically overrun by 35%. You have 4 database integration tasks in your schedule. What is the correct action?","opts":["Dismiss the AI finding — historical data does not apply to this project","Automatically add 35% to all 4 task durations","Investigate the 4 tasks with the technical lead, assess whether the historical overrun factors apply (complexity, team experience, tooling), and add schedule buffer where the AI''s pattern is confirmed to apply","Report the finding to the sponsor without further investigation"],"a":2,"exp":"AI pattern recognition is a risk identification input, not a direct schedule change command. Validate: Do the historical projects have similar complexity? Does this team have the same tooling? Has anything changed that makes overrun less likely? Add buffer where the analysis is confirmed, with documented rationale.","competency":"pm:risk"},
{"q":"What is the risk breakdown structure (RBS)?","opts":["A hierarchical chart of all project resources organized by risk","A hierarchical organization of risk categories used to ensure systematic risk identification across all project dimensions (technical, external, organizational, project management)","A list of risks ranked by priority","A network diagram showing risk dependencies"],"a":1,"exp":"The RBS is to risk identification what the WBS is to scope. Structured categories (technical risk: performance, security, integration; external risk: regulatory, vendor, market) prevent the team from only identifying obvious risks while missing systematic blind spots.","competency":"pm:risk"},
{"q":"What is the ''accept'' risk response strategy, and when is active acceptance appropriate versus passive acceptance?","opts":["Accepting means ignoring the risk entirely","Active acceptance: prepare a contingency plan to execute if the risk occurs; passive acceptance: acknowledge the risk exists but take no pre-emptive action — appropriate when the cost of response exceeds the EMV of the risk","Acceptance always means the sponsor takes responsibility","Acceptance is only for low probability risks"],"a":1,"exp":"Active acceptance: ''If the risk occurs, we will execute this specific contingency plan.'' Passive acceptance: ''We acknowledge this risk; if it occurs, we will deal with it ad hoc.'' Active acceptance is appropriate for medium-impact risks; passive is appropriate when the response cost significantly exceeds the risk''s EMV.","competency":"pm:risk"},
{"q":"During risk identification, the Delphi technique involves:","opts":["A single expert providing the definitive risk list","A voting system where the majority view prevails","Multiple rounds of anonymous questionnaires with experts, summarizing responses between rounds until consensus is reached — reducing groupthink and authority bias","A customer interview technique"],"a":2,"exp":"Delphi prevents anchoring (the first voice dominating) and authority bias (junior experts agreeing with seniors). Anonymity and iteration produce more accurate expert consensus. It is slower than a workshop but more reliable for high-stakes risk identification where diverse expert opinions are critical.","competency":"pm:risk"}
]'::jsonb);

-- ── MODULE 6: Financial Management ───────────────────────────────────────────
SELECT pg_temp.fill_pm_exam_a(6, '[
{"q":"At the end of Month 3, your project has a Planned Value (PV) of $120,000, an Earned Value (EV) of $90,000, and an Actual Cost (AC) of $105,000. What is the Cost Performance Index (CPI)?","opts":["0.86 — calculated as EV / AC = $90,000 / $105,000","0.75","1.14","1.33"],"a":0,"exp":"CPI = EV / AC = $90,000 / $105,000 = 0.857. A CPI below 1.0 means you are spending more than the value earned — the project is over budget. A CPI of 0.86 means for every $1 spent, $0.86 of value is delivered.","competency":"pm:finance"},
{"q":"Using the same data (PV=$120,000, EV=$90,000, AC=$105,000), what is the Schedule Performance Index (SPI)?","opts":["0.86","0.75 — calculated as EV / PV = $90,000 / $120,000","1.14","1.33"],"a":1,"exp":"SPI = EV / PV = $90,000 / $120,000 = 0.75. An SPI below 1.0 means you have delivered less value than planned — the project is behind schedule. An SPI of 0.75 means you are progressing at 75% of the planned rate.","competency":"pm:finance"},
{"q":"Your project Budget at Completion (BAC) is $500,000. At the current CPI of 0.80, what is the Estimate at Completion (EAC) using the formula EAC = BAC / CPI?","opts":["$400,000","$625,000 — calculated as $500,000 / 0.80","$580,000","$100,000"],"a":1,"exp":"EAC = BAC / CPI = $500,000 / 0.80 = $625,000. This formula assumes current efficiency continues for the rest of the project. It means the project is forecast to cost $625,000 against a $500,000 budget — a $125,000 overrun. Report this to the sponsor immediately.","competency":"pm:finance"},
{"q":"What is the Estimate to Complete (ETC)?","opts":["The budget remaining from the original plan","The expected cost to finish the remaining project work — calculated as EAC minus AC","The variance between planned and actual cost","The contingency reserve remaining"],"a":1,"exp":"ETC = EAC − AC. If EAC is $625,000 and AC is $105,000, ETC = $520,000. This is what you expect to spend from now until project completion. ETC is useful for cash flow forecasting and for telling the sponsor how much more budget will be required.","competency":"pm:finance"},
{"q":"You are asked to estimate a new project similar to one completed 18 months ago. Your organization has detailed cost data from the previous project. Which estimation technique is most appropriate?","opts":["Three-point PERT — because it accounts for uncertainty","Bottom-up estimation — it is always the most accurate","Analogous estimation — using the previous project''s actual costs as the basis, adjusted for known differences in size and complexity","Parametric estimation — using a cost-per-unit formula"],"a":2,"exp":"Analogous estimation uses actual historical data from comparable projects as the basis. It is fast and appropriate early in the project lifecycle when detailed scope is not yet defined. Adjust the analogue for known differences (e.g., 20% more complex, different technology) and document your adjustments.","competency":"pm:finance"},
{"q":"What is the To-Complete Performance Index (TCPI) and what does a value greater than 1.0 indicate?","opts":["TCPI measures schedule performance; >1.0 means ahead of schedule","TCPI = (BAC − EV) / (BAC − AC) — the cost efficiency required for the remaining work to meet the BAC; >1.0 means you must improve efficiency beyond current performance to stay within budget","TCPI = EV / AC; >1.0 means under budget","TCPI >1.0 means the project is on track"],"a":1,"exp":"TCPI = (BAC − EV) / (BAC − AC). If TCPI = 1.25, you must earn $1.25 of value for every $1.00 spent on remaining work to stay within the original budget. A TCPI significantly greater than your current CPI signals that the original budget may be unachievable.","competency":"pm:finance"},
{"q":"What is the difference between the cost baseline and the project budget?","opts":["They are the same document","The cost baseline is the time-phased approved cost plan used to measure performance; the project budget equals the cost baseline plus management reserve","The project budget excludes contingency; the cost baseline includes it","Management reserve is controlled by the PM; the cost baseline is controlled by the sponsor"],"a":1,"exp":"Cost baseline = cost estimates + contingency reserve (for identified risks), approved and time-phased. Project budget = cost baseline + management reserve (for unknown risks, controlled by sponsor). The PM measures earned value against the cost baseline, not the total project budget.","competency":"pm:finance"},
{"q":"A project sponsor asks why the project is behind schedule when the team has spent 90% of the budget with only 70% of the work complete. How do you explain this using earned value terminology?","opts":["The team is working inefficiently","The project has a Schedule Performance Index (SPI) below 1.0 — you have earned less value than planned — and a Cost Performance Index (CPI) below 1.0 — you are spending more than the value earned, indicating both schedule and cost problems","The budget forecast was incorrect","The project scope changed"],"a":1,"exp":"Spending 90% of budget (high AC) with only 70% of work done (low EV relative to AC) means CPI <1.0 — you are over budget for the work done. If the 70% done was supposed to be 80% at this point, SPI <1.0 — you are also behind schedule. Earned value makes both dimensions visible simultaneously.","competency":"pm:finance"},
{"q":"What is parametric cost estimation and when is it most appropriate?","opts":["Using team member opinion as the basis for cost estimates","Using a statistical relationship between historical data and project parameters — e.g., cost per function point, cost per square foot, cost per server — most appropriate when a reliable cost-per-unit relationship exists from historical data","Estimating costs bottom-up from individual work packages","Averaging three estimates: optimistic, most likely, pessimistic"],"a":1,"exp":"Parametric estimation: ''Software projects of this type cost $8,500 per function point; this project has 120 function points; estimated cost = $1,020,000.'' It is fast and defensible when the parameter relationship is statistically validated. It fails when the project differs significantly from the historical dataset.","competency":"pm:finance"},
{"q":"Bottom-up cost estimation is most appropriate when:","opts":["The project is in initiation and scope is undefined","Speed is more important than accuracy","The WBS is fully defined and individual work packages can be estimated from first principles — it provides the highest accuracy but requires the most time and effort","The project is similar to a previous project"],"a":2,"exp":"Bottom-up estimation builds cost from work package level up: estimate each component, sum them. It is the most accurate technique but requires a complete WBS, detailed scope, and significant estimating effort. It is appropriate for fixed-price contracts or projects where cost accuracy is critical.","competency":"pm:finance"},
{"q":"You receive a change request to add a feature that will cost $30,000 and take 3 weeks. The sponsor says ''just approve it and we''ll absorb the cost.'' What is your responsibility?","opts":["Approve it immediately since the sponsor has given authorization","Refuse — no changes are permitted once the budget is set","Process the change formally: update the cost and schedule baselines, update the WBS and risk register, document the approval, and communicate the new baselines to the team","Add the cost to contingency reserve without updating the baseline"],"a":2,"exp":"Even sponsor-approved changes require formal change control. The cost and schedule baselines must be updated to reflect the approved change. Without updating the baseline, earned value metrics will be distorted. The WBS, risk register, and stakeholder communication must also reflect the change.","competency":"pm:finance"},
{"q":"What is the three-point PERT cost estimate for a work package with an optimistic cost of $10,000, most likely cost of $20,000, and pessimistic cost of $40,000?","opts":["$23,333 — simple average of the three estimates","$21,667 — calculated as (O + 4M + P) / 6 = ($10,000 + $80,000 + $40,000) / 6","$20,000 — use the most likely estimate","$40,000 — always use the pessimistic estimate"],"a":1,"exp":"PERT three-point cost estimate: (O + 4M + P) / 6 = ($10,000 + 4×$20,000 + $40,000) / 6 = ($10,000 + $80,000 + $40,000) / 6 = $130,000 / 6 = $21,667. This provides a more statistically accurate estimate than the most likely alone by accounting for range uncertainty.","competency":"pm:finance"},
{"q":"Your project has BAC=$400,000, EV=$200,000, AC=$250,000, and PV=$220,000. What is the variance at completion (VAC)?","opts":["$50,000 over budget","−$100,000, indicating the project will likely overspend by $100,000 — calculated as BAC − EAC where EAC = BAC/CPI = $400,000/0.80 = $500,000; VAC = $400,000 − $500,000 = −$100,000","$20,000 under budget","Cannot be determined without the completion date"],"a":1,"exp":"CPI = EV/AC = $200,000/$250,000 = 0.80. EAC = BAC/CPI = $400,000/0.80 = $500,000. VAC = BAC − EAC = $400,000 − $500,000 = −$100,000. Negative VAC means the project is forecast to exceed budget. Report to the sponsor with corrective action options.","competency":"pm:finance"},
{"q":"An AI cost analytics tool projects that your project will finish $80,000 over budget based on current CPI trends. The sponsor has not yet been notified. What is the correct action?","opts":["Wait until the cost overrun is confirmed before communicating","Adjust the cost baseline to match the AI forecast without sponsor approval","Escalate to the sponsor immediately with the AI analysis, your own assessment, and options for corrective action (scope reduction, additional funding, schedule extension)","Ask the AI tool to recalculate with more optimistic assumptions"],"a":2,"exp":"A forecast significant cost overrun is a material project issue requiring immediate escalation. PMBOK requires PMs to communicate project status accurately and proactively. Waiting until the overrun is ''confirmed'' (i.e., already happened) violates the PM''s transparency obligation and eliminates time for corrective action.","competency":"pm:finance"},
{"q":"What is the purpose of a cost management plan?","opts":["To set the project budget","To document how project costs will be planned, estimated, budgeted, managed, and controlled — including units of measure, precision levels, thresholds for variance reporting, and earned value rules","To list all project expenses","To approve invoices from vendors"],"a":1,"exp":"The cost management plan is the governance document for all cost-related processes. It establishes: what currency and precision level to use, what variance threshold triggers corrective action (e.g., CPI <0.90), which EAC formula to use, and who approves budget changes at each level. Without it, cost management is improvised.","competency":"pm:finance"}
]'::jsonb);

-- ── MODULE 7: Stakeholder & Communication ─────────────────────────────────────
SELECT pg_temp.fill_pm_exam_a(7, '[
{"q":"A senior executive has high power and high interest in your project but has been disengaged in recent status meetings. Using the power/interest grid, what is the appropriate engagement strategy, and what should you do about her disengagement?","opts":["She is ''keep satisfied'' — send more emails","She is ''manage closely'' — investigate the root cause of disengagement (does she feel uninformed? Is the format wrong?), adjust your approach, and re-engage proactively with a one-on-one briefing","She is ''monitor'' — low effort is appropriate since she has not escalated","Move her to a lower interest category to reduce reporting burden"],"a":1,"exp":"High power, high interest = Manage Closely. Disengagement from a key stakeholder is a risk signal, not an invitation to reduce effort. Root causes include: wrong communication format, information overload, unresolved concerns, or feeling their input is not valued. A one-on-one conversation surfaces the real issue.","competency":"pm:stakeholders"},
{"q":"What is the RAG status system used in executive project reporting?","opts":["A risk assessment grid (Risk, Action, Gap)","A Red/Amber/Green status system: Red = significant issue requiring immediate attention; Amber = potential issue requiring monitoring; Green = on track — enabling executives to quickly identify projects requiring intervention","A resource allocation grid","A reporting frequency system (Regular, As-needed, Governance)"],"a":1,"exp":"RAG status enables exception-based reporting: executives scan for Red and Amber projects; Green projects need no intervention. The PM must set clear criteria for each status level — a project cannot be Amber for months without escalation. Vague RAG reporting erodes stakeholder trust.","competency":"pm:stakeholders"},
{"q":"A key stakeholder consistently misses project review meetings and does not respond to emails. What is the most effective PM response?","opts":["Send escalating volumes of emails until they respond","Remove them from the stakeholder register","Directly engage their manager without speaking to them first","Reach out directly to understand their preferred communication method, adjust your approach, and if the engagement gap creates project risk, escalate appropriately to the sponsor"],"a":3,"exp":"Non-responsive stakeholders often have a communication preference mismatch (email vs. phone), bandwidth constraints, or unclear understanding of why their input matters. The PM should first try direct outreach in a different format. Escalation is appropriate if the engagement gap creates project risk.","competency":"pm:stakeholders"},
{"q":"What is principled negotiation (Harvard model) and how does a PM apply it in stakeholder conflicts?","opts":["Always accept the stakeholder''s position to maintain the relationship","Win-lose negotiation where the PM fights for the project''s interests at all costs","A negotiation approach focused on separating people from the problem, focusing on interests not positions, generating mutual-gain options, and insisting on objective criteria — producing durable agreements","Negotiating through the sponsor to avoid direct conflict"],"a":2,"exp":"Principled negotiation (Fisher & Ury): (1) Separate people from problem — the stakeholder is not the enemy. (2) Focus on interests not positions — why does the stakeholder want this? (3) Generate options for mutual gain. (4) Use objective criteria (data, standards) to evaluate options. Produces agreements both parties actually honor.","competency":"pm:stakeholders"},
{"q":"Your project communication plan specifies weekly status reports emailed to all stakeholders. A senior executive tells you she prefers a 5-minute verbal briefing on Fridays instead. What should you do?","opts":["Maintain the email report — the communication plan must be followed consistently","Update the communication plan to include the Friday briefing for this executive — communication plans should be tailored to stakeholder preferences","Convince the executive that email is more efficient","Send the email report and call her every Friday to read it aloud"],"a":1,"exp":"Communication plans are not rigid mandates — they are frameworks. Stakeholder communication preferences should be honored when feasible. Update the plan to reflect the verbal briefing, document it as the agreed approach for this executive, and continue improving the plan as you learn stakeholder preferences.","competency":"pm:stakeholders"},
{"q":"What information should a weekly project status report contain at a minimum?","opts":["Only milestone completion dates","RAG status, accomplishments this period, planned activities next period, issues requiring decisions, risks requiring escalation, and budget/schedule variance summary","A full list of all tasks completed","Technical specifications of deliverables completed this week"],"a":1,"exp":"An effective status report answers: Where are we (RAG)? What did we accomplish? What are we doing next? What do we need from you (decisions, escalations)? What are the numbers (schedule, cost variance)? More detail than this creates reading burden; less creates information gaps.","competency":"pm:stakeholders"},
{"q":"During a stakeholder analysis, you identify that the VP of Operations (high power) is resistant to the project because she fears it will disrupt her team''s workflows. What is the most effective engagement strategy?","opts":["Proceed without her support — her power does not mean she can block the project","Escalate to the CEO to force her cooperation","Engage her directly to understand her specific concerns, involve her team in requirements and design decisions, and develop a change management plan that addresses operational continuity","Send her detailed technical documentation about the project"],"a":2,"exp":"Resistant high-power stakeholders are the most dangerous. Their concerns are often legitimate — projects do disrupt operations. Engaging her concerns directly, involving her team in design, and demonstrating operational continuity planning converts a resistor to a supporter or at minimum reduces active opposition.","competency":"pm:stakeholders"},
{"q":"An AI communication tool analyzes your stakeholder email responses and flags that three board members show declining engagement (shorter replies, longer response times). What action should you take?","opts":["Ignore the AI analysis — email behavior is not a reliable engagement signal","Immediately send longer, more detailed emails to the three board members","Use the AI insight as a signal to proactively reach out to these three stakeholders to check in, understand their concerns, and assess whether the communication format or frequency needs adjustment","Reduce communication frequency since they appear to prefer less contact"],"a":2,"exp":"AI communication analytics provide early warning signals that human intuition might miss. Declining engagement from board members could indicate: information overload, unresolved concerns, or declining confidence in the project. Proactive outreach to understand the root cause is far more effective than either increasing email volume or reducing contact.","competency":"pm:stakeholders"},
{"q":"What is a RACI chart and how does it resolve stakeholder communication confusion?","opts":["A risk analysis and change impact chart","A matrix assigning Responsible, Accountable, Consulted, and Informed roles to each project activity — ensuring every activity has exactly one Accountable party and clarifying who needs to be involved versus informed","A resource allocation and cost impact matrix","A communication frequency and channel chart"],"a":1,"exp":"RACI eliminates the most common team conflicts: who decides? who needs to be consulted? who just needs to know? Responsible = does the work. Accountable = owns the outcome (only one per activity). Consulted = input required before decision. Informed = notified after decision. Every row must have exactly one A.","competency":"pm:stakeholders"},
{"q":"A project stakeholder complains that they ''never know what is happening'' on the project, despite receiving the weekly status report. What does this most likely indicate?","opts":["The stakeholder is not paying attention to communications","The status report format or content does not meet this stakeholder''s information needs — the PM should investigate what specific information they are missing and redesign the report or supplement it","The stakeholder''s expectations are unreasonable","The project is too complex to communicate effectively"],"a":1,"exp":"''I never know what''s happening'' means the current communication is not working for this person. The PM investigates: What specific decisions are they making that lack information? What format do they prefer? What frequency? Assuming the stakeholder is at fault instead of diagnosing the communication gap is a common PM failure.","competency":"pm:stakeholders"},
{"q":"What is the difference between a push communication and a pull communication strategy?","opts":["Push is faster; pull is more accurate","Push sends information to recipients proactively (email, status reports, presentations); pull makes information available for stakeholders to access on demand (SharePoint, project portals) — most effective communication plans use both","Pull is only for technical stakeholders; push is for executives","Push requires stakeholder approval; pull does not"],"a":1,"exp":"Push ensures key stakeholders receive time-sensitive information without needing to seek it. Pull supports stakeholders who want depth (project schedule, detailed reports, risk logs) without imposing that detail on everyone. Communication plans should map each stakeholder to the right mix of push and pull channels.","competency":"pm:stakeholders"},
{"q":"During a project post-mortem, team members reveal they had concerns about a technical approach for weeks but did not raise them. What communication failure does this represent?","opts":["The team was not technically competent","A psychological safety failure — team members did not feel safe raising concerns; the PM should establish explicit norms where raising issues is valued and never punished","Poor documentation practices","Inadequate meeting frequency"],"a":1,"exp":"Psychological safety (Edmondson) is the belief that raising concerns is safe. Projects where bad news is punished become projects where bad news is hidden — until it becomes a crisis. PMs establish safety by thanking people for raising concerns, never shooting messengers, and visibly acting on issues raised.","competency":"pm:stakeholders"},
{"q":"A project sponsor is asking for daily briefings. The project is on track and there are no significant issues. How do you manage this expectation appropriately?","opts":["Provide daily briefings regardless — the sponsor always gets what they request","Reduce briefings to monthly without discussing it","Discuss the briefing cadence with the sponsor, propose a weekly briefing with an option to request daily updates during periods of high risk or issue activity — documenting the agreed approach in the communication plan","Delegate sponsor briefings to the project coordinator"],"a":2,"exp":"Daily briefings on a green project consume significant PM time with little incremental value. The PM negotiates: propose weekly with a clear commitment to proactively reach out immediately if status changes to Amber or Red. Most sponsors accept this when the PM frames it as respecting their time while ensuring no surprises.","competency":"pm:stakeholders"},
{"q":"What is stakeholder engagement assessment, and when should the PM update it?","opts":["A one-time analysis completed during initiation","A continuous assessment tracking each stakeholder''s current engagement level versus desired engagement level (unaware → resistant → neutral → supportive → leading), updated as engagement conditions change throughout the project","A satisfaction survey administered at project closure","An analysis completed only when stakeholders escalate concerns"],"a":1,"exp":"Stakeholder engagement is not static — it changes as the project evolves. A stakeholder who was supportive in initiation may become resistant after a deliverable falls short of expectations. The PM tracks current vs. desired engagement and actively moves stakeholders toward the desired level through tailored actions.","competency":"pm:stakeholders"},
{"q":"What is the most effective format for communicating project schedule variance to a non-PM executive audience?","opts":["A detailed Gantt chart with all 200 tasks and dependencies","The complete network diagram with critical path highlighted","A milestone-only summary showing completed vs. planned dates, overall schedule variance in days, and current RAG status — supplemented by verbal explanation of cause and corrective action","A narrative report without any visual elements"],"a":2,"exp":"Executives make decisions, not plans. A milestone summary answers their question: Are we on track, and if not, by how much and why? A 200-task Gantt chart creates noise that obscures the signal. Supplement visuals with a crisp verbal narrative: what happened, what we are doing about it, what we need from them.","competency":"pm:stakeholders"}
]'::jsonb);

-- ── MODULE 8: Team Leadership ─────────────────────────────────────────────────
SELECT pg_temp.fill_pm_exam_a(8, '[
{"q":"Your newly formed project team is struggling with unclear roles, competing ideas about how to work, and some interpersonal tension. According to Tuckman''s model, which stage is the team in, and what should the PM do?","opts":["Performing — this is normal and no PM intervention is needed","Norming — the team is establishing its working norms and needs less support","Storming — the PM should establish clear roles, facilitate conflict resolution, and create structured working agreements to move the team toward norming","Forming — the PM should immediately replace resistant team members"],"a":2,"exp":"Storming is characterized by conflict over roles, processes, and authority — a normal development stage. The PM''s role in storming is not to eliminate conflict but to channel it productively: clarify roles via RACI, facilitate working agreements, and model constructive disagreement. Teams that skip storming often have hidden conflicts that surface later.","competency":"pm:leadership"},
{"q":"According to Herzberg''s two-factor theory, which of the following is a motivator (not just a hygiene factor)?","opts":["A competitive salary","Good working conditions","Job security","Recognition for achievement, responsibility, and opportunities for growth — intrinsic factors that produce genuine motivation"],"a":3,"exp":"Herzberg distinguishes hygiene factors (salary, working conditions, job security) — their absence causes dissatisfaction, but their presence does not motivate — from motivators (achievement, recognition, responsibility, growth) that actually increase engagement. PMs who only manage compensation and conditions miss the drivers of high performance.","competency":"pm:leadership"},
{"q":"A team member consistently delivers work late and below quality standards. You have had one informal conversation but no improvement. What is the appropriate PM escalation path?","opts":["Immediately request HR remove them from the project","Accept the performance gap — the PM has no authority over team members","Provide specific written feedback documenting expected vs. actual performance, agree on a measurable improvement plan with clear timeframes, follow up as agreed, and escalate to the functional manager if the improvement plan is not met","Redistribute their work to other team members without addressing the issue"],"a":2,"exp":"Performance management follows a structured path: informal feedback → formal written feedback with improvement plan → escalation to functional manager if unresolved. Skipping steps exposes the PM to pushback (''you never told me clearly''). Documentation protects both the PM and the team member.","competency":"pm:leadership"},
{"q":"What does a RACI matrix define, and why must each deliverable have exactly one Accountable party?","opts":["RACI assigns tasks to team members; multiple Accountable parties share responsibility","RACI defines Responsible, Accountable, Consulted, Informed roles; exactly one Accountable per deliverable because diffused accountability is no accountability — when everyone is accountable, no one is","RACI is a scheduling tool showing task dependencies","RACI defines Responsible, Available, Committed, and Informed roles"],"a":1,"exp":"When two people are both ''Accountable,'' each assumes the other is handling issues. The single-Accountable rule forces explicit ownership. The Accountable party can delegate work (Responsible) but cannot delegate their ownership of the outcome. For PMs, this is the most common conflict source to resolve at project start.","competency":"pm:leadership"},
{"q":"Your project team has been working together for 8 months, is delivering consistently, and members proactively cover for each other without being asked. According to Tuckman''s model, which stage is this?","opts":["Storming — high conflict remains","Norming — they are still establishing processes","Performing — the team operates as a self-managing, high-trust unit focused on results","Adjourning — they are preparing to wind down"],"a":2,"exp":"Performing teams demonstrate: high trust, shared ownership, proactive problem-solving, and minimal need for PM oversight of daily work. The PM''s role shifts from directive to supportive — removing organizational obstacles while the team manages its own day-to-day operations.","competency":"pm:leadership"},
{"q":"A remote team member in a different time zone consistently speaks last in meetings and mentions feeling ''left out of key decisions.'' What is the most effective PM intervention?","opts":["Schedule all meetings at the remote team member''s local morning time","Dismiss the concern — working across time zones requires adapting","Document async decisions so the remote team member can review and comment; rotate meeting times to share timezone burden; and explicitly invite their input at the start of meetings before others have anchored the discussion","Ask the remote team member to improve their own availability"],"a":2,"exp":"Remote team members who speak last are disadvantaged by anchoring bias — their views are shaped by everything already said. Proactive inclusion: async decision documentation with comment periods, rotating meeting times, and explicit early invitation for input combat the structural disadvantage of timezone separation.","competency":"pm:leadership"},
{"q":"What is the SBI (Situation-Behavior-Impact) model, and how does a PM use it to give constructive feedback?","opts":["A project status reporting model (Schedule, Budget, Issues)","A feedback model: Situation (when/where), Behavior (what you specifically observed), Impact (the effect on the team/project) — providing specific, actionable feedback without generalization or personal judgment","A stakeholder engagement model","A risk identification model"],"a":1,"exp":"SBI: ''In yesterday''s sprint review (situation), you interrupted the client three times before they finished their feedback (behavior), which caused them to stop sharing concerns — we may have missed important requirements (impact).'' SBI is specific, factual, and focused on observable behavior rather than personality — enabling the recipient to understand and change the behavior.","competency":"pm:leadership"},
{"q":"A team member approaches you and says they are ''burned out'' and thinking about leaving the project. What should the PM do first?","opts":["Report the risk to the sponsor immediately","Tell the team member that the deadline cannot change and they need to push through","Listen actively to understand the specific sources of stress, assess whether workload, interpersonal issues, or unclear direction are the primary causes, and work collaboratively on solutions before escalating or making assumptions","Immediately assign their work to another team member to reduce their load"],"a":2,"exp":"Burnout is a signal of systemic problems: unsustainable workload, unclear priorities, or lack of recognition. The PM listens first to diagnose the specific causes before acting. Solutions might include workload rebalancing, clearer priority guidance, or recognition. Jumping to ''reduce their load'' without diagnosis may solve the wrong problem.","competency":"pm:leadership"},
{"q":"What is the difference between a PM''s formal authority and their influence, and why is influence more important in matrix organizations?","opts":["Formal authority is always stronger than influence","Formal authority (title-based) and influence are equally important in all organizations","In matrix organizations, team members report to functional managers, not the PM — so the PM has limited formal authority over team members and must rely on influence (relationships, expertise, reciprocity) to motivate and direct","Influence is only relevant for external stakeholders"],"a":2,"exp":"In matrix environments, the PM cannot hire/fire/promote team members — those decisions belong to functional managers. PMs who rely on formal authority in matrix organizations stall. Influence — built through expertise, relationships, integrity, and reciprocity — is the primary leadership currency for project managers.","competency":"pm:leadership"},
{"q":"An AI team analytics tool reports that one team member''s commit frequency has dropped 60% over the past two weeks and their meeting participation score has declined. What is the correct PM action?","opts":["Issue a formal performance warning immediately","Ignore the data — productivity metrics are dehumanizing","Use the AI data as a signal to have a private, empathetic check-in conversation with the team member — asking how they are doing before discussing performance — treating the data as context, not accusation","Share the AI metrics with the entire team to create accountability"],"a":2,"exp":"AI productivity signals are inputs to human judgment, not HR verdicts. A drop in output can indicate: personal challenges, unclear direction, technical blockers, or interpersonal issues. A private empathetic conversation surfaces the real cause. Leading with the data as an accusation damages trust and rarely solves the underlying problem.","competency":"pm:leadership"},
{"q":"What is the adjourning stage in Tuckman''s model, and what is the PM''s responsibility at this stage?","opts":["The team is dissolving — the PM has no further responsibility","The team continues to perform indefinitely — there is no adjourning stage","The final stage where the project concludes: the PM facilitates knowledge capture, recognizes team contributions, conducts lessons learned, and manages the emotional transition as team members move to other assignments","Adjourning occurs between storming and norming"],"a":2,"exp":"Adjourning involves emotional transition — team members who have worked closely experience genuine loss. The PM''s responsibility: formally recognize contributions, conduct meaningful lessons learned, capture institutional knowledge, ensure smooth resource transition, and close out the project with appropriate celebration.","competency":"pm:leadership"},
{"q":"A team member disagrees with a technical approach decision you have made and is vocal about it in team meetings. How should you handle this?","opts":["Assert your authority as PM — the decision has been made","Avoid discussing it to prevent team conflict","Invite a private conversation to understand their concern fully, genuinely evaluate whether their technical objection has merit, revise the decision if they are correct, or explain your reasoning more fully if the decision stands — and stop public challenges after the decision is final","Ask the team to vote on the technical approach"],"a":2,"exp":"Technical objections from practitioners often contain valid information. The PM should: take the concern seriously, evaluate it privately, and change the decision if warranted (this builds credibility). If the decision stands, explain why — then expect the team member to support the decision publicly even if they disagree privately.","competency":"pm:leadership"},
{"q":"What is the most effective approach to managing team conflict between two team members whose interpersonal friction is affecting delivery?","opts":["Separate the two team members completely to eliminate interaction","Ignore it — personal conflicts are not the PM''s responsibility","Speak with each team member separately to understand their perspective, facilitate a joint conversation focused on project impact and resolution behaviors, and establish clear expectations for professional conduct — escalating to HR only if professional resolution attempts fail","Assign blame to the team member who raised the conflict first"],"a":2,"exp":"Team conflict managed correctly becomes constructive; ignored, it becomes corrosive. The PM''s sequence: private conversations to understand each perspective → joint facilitated conversation focused on behaviors and project impact → agreed resolution → follow-up. HR escalation is a last resort, not a first response.","competency":"pm:leadership"},
{"q":"You are building a cross-functional team for a 9-month project. What team norms should you establish in the first week to maximize performance?","opts":["Technical coding standards only","Meeting schedules only","Communication channels and response-time expectations, decision-making authority, conflict resolution process, definition of done for deliverables, and how the team will give each other feedback — documented and agreed by the team, not imposed by the PM","Performance review criteria"],"a":2,"exp":"Norms established in forming prevent conflicts in storming. The team should co-create (not receive) norms about: how we communicate, how we decide, how we handle disagreement, what ''done'' means. Team-created norms have far higher compliance than PM-dictated rules.","competency":"pm:leadership"},
{"q":"A high-performing team member is offered a promotion that would require them to leave the project mid-execution. How do you balance the team member''s career interests with project needs?","opts":["Block the promotion until the project ends","Accept the team member''s immediate departure without any planning","Congratulate the team member genuinely, negotiate a transition timeline with HR and the receiving team, ensure knowledge transfer is completed, and update the risk register and resource plan for the backfill — advocating for the team member while protecting the project","Do nothing — this is HR''s problem to manage"],"a":2,"exp":"High-performing team members'' career growth is a PM''s leadership obligation, not a threat. Blocking promotions destroys trust and reputation. The PM negotiates a reasonable transition (typically 2–4 weeks), drives knowledge transfer, and uses the event to update succession planning. This also demonstrates to the remaining team that you advocate for their growth.","competency":"pm:leadership"}
]'::jsonb);

-- ── MODULE 9: Procurement ─────────────────────────────────────────────────────
SELECT pg_temp.fill_pm_exam_a(9, '[
{"q":"Your organization needs a specialized data analytics capability. An internal team could build it in 6 months for $400,000 with moderate risk. A vendor offers a proven SaaS solution for $150,000/year. What framework structures this decision?","opts":["ROI analysis only","A make-or-buy analysis comparing total cost of ownership, strategic fit, build risk, internal capability, and vendor dependency over the expected useful life of the capability","A simple cost comparison for year one only","A vendor scoring matrix"],"a":1,"exp":"Make-or-buy analysis considers: TCO (not just year-one cost), strategic differentiation (is this a core competency worth owning?), build risk (can we actually deliver?), internal capability, and vendor dependency. The SaaS option may cost more over 5 years than building but with lower risk — quantify both scenarios over the expected lifetime.","competency":"pm:procurement"},
{"q":"You are procuring a vendor to build a custom software system. Requirements are well-defined and the scope is unlikely to change. Which contract type provides the most cost protection for your organization?","opts":["Time and Materials (T&M) — because it pays only for actual work","Cost-Reimbursable (CR) — because the vendor recovers all costs","Fixed Price (FP) — because the vendor accepts the cost risk for delivering a defined scope","Indefinite Delivery / Indefinite Quantity (IDIQ) — because it offers maximum flexibility"],"a":2,"exp":"Fixed-price contracts transfer cost risk to the vendor — they commit to delivering defined scope for a fixed price. This works when scope is well-defined and stable. If scope changes, the vendor will issue change orders. CR contracts protect the vendor; T&M balances risk. FP is the buyer''s preferred structure for well-defined work.","competency":"pm:procurement"},
{"q":"You are contracting a vendor for an 18-month digital transformation engagement. Requirements will evolve as the project progresses. Which contract type is most appropriate?","opts":["Firm Fixed Price — it incentivizes the vendor to be efficient","Time and Materials — because it accommodates scope evolution while paying for actual time and materials used","Cost Plus Fixed Fee — it provides the maximum cost protection","Lump Sum — it gives the vendor flexibility to manage costs"],"a":1,"exp":"T&M contracts are appropriate for evolving scope because you pay for actual effort rather than committing to a fixed deliverable. The risk: without a ceiling, costs can escalate. Mitigate with a not-to-exceed clause (T&M NTE) and active monitoring. Fixed price on undefined scope drives vendors to limit scope or build in large contingency.","competency":"pm:procurement"},
{"q":"What should a well-structured RFP (Request for Proposal) include to enable fair vendor evaluation?","opts":["Company background information only","A project description, technical requirements, functional requirements, evaluation criteria and weighting, submission format requirements, timeline, and contract terms — enabling all vendors to respond to the same specification","Only the budget and desired delivery date","A list of preferred vendors with evaluation scores already assigned"],"a":1,"exp":"An RFP with clear evaluation criteria (weighted scoring) enables objective comparison. Without specified criteria, evaluation becomes subjective and defensible only as opinion. Weightings reflect priorities: if security compliance is paramount, its weight should reflect that. Standard format requirements make comparison practical.","competency":"pm:procurement"},
{"q":"During vendor evaluation, your preferred vendor scores 87/100 on technical criteria but 12% higher in price than the second-ranked vendor who scores 79/100. How should you approach this decision?","opts":["Always select the lowest-cost vendor regardless of technical score","Always select the highest technical score regardless of cost","Conduct a weighted evaluation including both technical score and total cost of ownership, present the trade-off analysis to the decision-maker, and make a documented recommendation that considers strategic factors beyond the scorecard","Select the highest-scoring vendor without cost consideration"],"a":2,"exp":"Procurement decisions involve value, not just cost. An 8-point technical advantage may represent less risk, faster delivery, or better long-term capability — worth the price premium. Present the trade-off to the decision-maker with quantified analysis. The PM''s job is to inform the decision, not to automatically select the cheapest or highest-scoring option in isolation.","competency":"pm:procurement"},
{"q":"A vendor misses a contractual milestone without notifying your organization. According to the vendor governance framework, what is the PM''s immediate response?","opts":["Wait for the vendor to self-correct before escalating","Issue a payment hold without formal notification","Issue a formal written notice of breach per the contract terms, document the impact on the project schedule and cost, escalate per the escalation matrix, and require a corrective action plan from the vendor within the contracted response period","Terminate the contract immediately"],"a":2,"exp":"Contract management requires documented responses to breaches. Informal conversations are not sufficient — written notice creates the legal record required if the issue escalates to dispute resolution or termination. The corrective action plan establishes the vendor''s accountability path.","competency":"pm:procurement"},
{"q":"What is a Service Level Agreement (SLA) in vendor governance, and what should happen when an SLA is consistently breached?","opts":["An SLA is a vendor''s marketing promise with no contractual weight","An SLA is a contractual commitment defining minimum service levels (uptime, response time, resolution time), usually with financial penalties (service credits) for breaches; consistent breaches should trigger an escalation meeting, root cause analysis, and if unresolved, contract remedies including termination","An SLA is only relevant for IT service contracts","SLA breaches should be overlooked to maintain vendor relationships"],"a":1,"exp":"SLAs have contractual teeth. Service credits (financial penalties) for breaches are the primary enforcement mechanism. Consistent breaches despite credits indicate a systemic vendor performance problem. The PM escalates to vendor management, requests a corrective action plan, and documents the pattern to support termination if needed.","competency":"pm:procurement"},
{"q":"What is the difference between a competitive bid (IFB/ITB) and an RFP procurement process?","opts":["They are identical processes","An IFB/ITB selects the lowest compliant bid with no qualitative evaluation; an RFP includes qualitative evaluation of solution approach, team, and technical merit — used when quality and approach matter as much as price","IFB is for services; RFP is for goods","RFP is used for small purchases; IFB is for large contracts"],"a":1,"exp":"IFB (Invitation for Bid): award goes to lowest compliant bid — price is the only differentiator (commodity purchases, construction with clear specifications). RFP (Request for Proposal): evaluates approach, team, and quality alongside price — used when how the vendor will deliver matters as much as what they will deliver.","competency":"pm:procurement"},
{"q":"An AI tool analyzes 50 vendor proposals and ranks them by compliance with your RFP requirements. The top-ranked vendor by the AI has no references in your industry. How should you use this AI analysis?","opts":["Award the contract to the AI''s top-ranked vendor immediately","Dismiss the AI analysis and conduct manual review from scratch","Use the AI ranking as an efficient starting point for shortlisting, but supplement with qualitative assessment: reference checks in your industry, a vendor presentation, and evaluation of the vendor''s understanding of your specific context — the AI assesses compliance, not fit","Accept all AI rankings without modification"],"a":2,"exp":"AI excels at systematic compliance checking across large proposal sets — a task that would take weeks manually. But AI cannot assess cultural fit, reference quality, industry context, or the ''how'' behind compliance checkboxes. The PM uses AI for efficiency in screening, and human judgment for the qualitative factors that determine real-world success.","competency":"pm:procurement"},
{"q":"Your organization is procuring a vendor to staff a 2-year project. You want to minimize organizational risk if the project ends early or vendor performance is poor. Which contract feature should you require?","opts":["A long-term exclusivity clause that locks the vendor to your project","A termination for convenience clause — allowing the organization to terminate the contract with defined notice and payment for completed work, without requiring the vendor to be in breach","A fixed-price clause that eliminates cost overrun risk","A payment-upon-delivery clause that delays all payments until project completion"],"a":1,"exp":"Termination for convenience clauses protect the buyer from being locked into a non-performing or no-longer-needed vendor contract. It specifies: notice period (typically 30–90 days), payment for work completed, and any wind-down costs. Without it, terminating a vendor requires proving breach — a much higher legal bar.","competency":"pm:procurement"},
{"q":"What KPIs should a vendor governance framework include for a software development vendor?","opts":["Only delivery milestone dates","Delivery milestone adherence, defect rate, defect resolution time, test coverage, security incident count, sprint velocity against committed velocity, and stakeholder satisfaction score — providing a multi-dimensional performance picture","Only budget adherence","Only the number of features delivered"],"a":1,"exp":"Single-metric vendor governance creates gaming. A vendor who hits milestone dates by cutting corners on quality will score well on schedule but poorly on defect rate. Multi-dimensional KPIs force holistic performance. Review KPIs monthly; escalate if any single KPI breaches threshold for two consecutive periods.","competency":"pm:procurement"},
{"q":"What is a cost-reimbursable contract with award fee (CPAF), and when is it most appropriate?","opts":["A contract where the vendor charges cost plus a fixed percentage — used for all projects","A contract where the vendor is reimbursed for all allowable costs plus a base fee, with an additional award fee determined by the buyer''s subjective assessment of performance — most appropriate when excellent performance is desired and can be evaluated but cannot be objectively specified in advance","A contract where the vendor pays for its own costs if they exceed the estimate","A fixed-price contract with a bonus for early delivery"],"a":1,"exp":"CPAF is used when the buyer wants to incentivize superior performance on subjective criteria (innovation, responsiveness, quality above minimum) that cannot be contractually specified precisely. The award fee decision process and criteria must be defined at contract execution to prevent disputes.","competency":"pm:procurement"},
{"q":"A vendor claims their delay was caused by your organization failing to provide timely decisions. The contract requires you to respond within 5 business days. Your records show responses took 12–15 days on three occasions. What is the PM''s accountability here?","opts":["Deny the claim — vendors always blame buyers","Accept full financial liability for all vendor-claimed costs","Acknowledge that decision delays occurred (the records support the claim), quantify the schedule and cost impact attributable to the delay, negotiate a fair adjustment per the contract''s delay clause, and implement a decision-tracking process to prevent recurrence","Terminate the contract to avoid liability"],"a":2,"exp":"Procurement contracts impose mutual obligations. If the buyer caused delay through missed decision SLAs, the contract likely entitles the vendor to an equitable adjustment. Acknowledging the facts while quantifying and negotiating the fair adjustment is both legally appropriate and relationship-preserving. Denial when records contradict the position damages credibility.","competency":"pm:procurement"},
{"q":"What is the purpose of a Procurement Management Plan?","opts":["To list all vendors the organization has used historically","To document how procurement activities will be planned, executed, and controlled: what will be procured, which contract types, how vendors will be selected, what metrics will be used for governance, and how contract changes will be managed","To define the project budget","To specify technical requirements for vendor systems"],"a":1,"exp":"The Procurement Management Plan is the governance framework for all buying activities. Without it, procurement decisions are ad hoc — contract types vary inconsistently, evaluation criteria differ across procurements, and vendor governance is informal. The plan creates organizational consistency and reduces procurement risk.","competency":"pm:procurement"},
{"q":"An AI procurement tool identifies that a vendor in your current proposal pool was involved in a data breach at another client 8 months ago. This is not in the vendor''s RFP response. What should you do?","opts":["Disqualify the vendor without giving them an opportunity to respond","Ignore the finding — the AI may have unreliable data","Raise the finding with your procurement and legal team, request clarification from the vendor about the incident and their remediation actions, and include security posture as a formal evaluation criterion if it is not already — making an informed decision with the complete picture","Award the contract and address security through the SLA"],"a":2,"exp":"AI due diligence findings are inputs requiring validation and formal process. A security incident 8 months ago may be fully remediated or may indicate ongoing systemic risk — only the vendor''s explanation and your security team''s assessment can determine which. Formal evaluation of security posture protects your organization and is defensible.","competency":"pm:procurement"}
]'::jsonb);

-- Verification
SELECT ch.order_index, ch.title, COUNT(qq.id) as question_count
FROM public.quiz_questions qq
JOIN public.quizzes qz ON qq.quiz_id = qz.id
JOIN public.chapters ch ON qz.chapter_id = ch.id
JOIN public.courses co ON ch.course_id = co.id
WHERE co.title = 'AI Project Manager & Delivery Leader'
  AND ch.order_index IN (1, 2, 3, 4, 5, 6, 7, 8, 9)
GROUP BY ch.order_index, ch.title
ORDER BY ch.order_index;
-- Expected: 9 rows, each with question_count = 15
